import{_ as i,o as s,c as a,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/vorbereitung/gruppenprozesse-noten-mahnungen-fs-1.png",o="/bilder/vorbereitung/gruppenprozesse-noten-mahnungen-fs-2-eingabemaske.png",l="/bilder/vorbereitung/gruppenprozesse-noten-mahnungen-fs-3-erweiterte-noten.png",z=JSON.parse('{"title":"Noten, Mahnungen und fachbezogene Fehlstunden eingeben","description":"","frontmatter":{"title":"Noten, Mahnungen und fachbezogene Fehlstunden eingeben","source_pageid":475,"source_revision":5390},"headers":[],"relativePath":"zeugnisse/vorbereitung/noten-mahnungen-und-fehlstd-eingeben-gruppenprozesse-noten-zeugnisvorbereitung.md","filePath":"zeugnisse/vorbereitung/noten-mahnungen-und-fehlstd-eingeben-gruppenprozesse-noten-zeugnisvorbereitung.md"}'),h={name:"zeugnisse/vorbereitung/noten-mahnungen-und-fehlstd-eingeben-gruppenprozesse-noten-zeugnisvorbereitung.md"};function d(g,r,c,p,m,b){return s(),a("div",null,[...r[0]||(r[0]=[t('<h1 id="noten-mahnungen-und-fachbezogene-fehlstunden-eingeben" tabindex="-1">Noten, Mahnungen und fachbezogene Fehlstunden eingeben <a class="header-anchor" href="#noten-mahnungen-und-fachbezogene-fehlstunden-eingeben" aria-label="Permalink to &quot;Noten, Mahnungen und fachbezogene Fehlstunden eingeben&quot;">​</a></h1><p>Erfassen Sie Werte für einen gewählten Lernabschnitt und eine zuvor ausgewählte Schülergruppe. Sortierung und zusätzliche Filter helfen bei der Eingabe nach Fach, Schüler oder Kurs.</p><p><a href="/bilder/vorbereitung/gruppenprozesse-noten-mahnungen-fs-1.png"><img src="'+u+'" alt="Anstoßen des Gruppenprozesses, um nach einer bestimmten Sortierung oder klassen- oder kursweise Note, Mahnungen und Fehlstunden einzugeben." loading="lazy"></a></p><p><em>Anstoßen des Gruppenprozesses, um nach einer bestimmten Sortierung oder klassen- oder kursweise Note, Mahnungen und Fehlstunden einzugeben.</em></p><p>Dieser Gruppenprozess ermöglicht es, für eine größere Schülermenge Noten, Mahnungen oder Fehlstunden einzugeben.</p><p>Über eine Filterung im Container kann schon eine Vorauswahl der zu bearbeitenden Schüler getroffen werden, zum Beispiel auf einen Jahrgang oder eine Klasse. Diese Auswahl wird dann im Prozess selbst nach Wahl noch verfeinert.</p><h2 id="_1-lernabschnitt-und-sortierung-wahlen" tabindex="-1">1. Lernabschnitt und Sortierung wählen <a class="header-anchor" href="#_1-lernabschnitt-und-sortierung-wahlen" aria-label="Permalink to &quot;1. Lernabschnitt und Sortierung wählen&quot;">​</a></h2><p>Zuerst werden Schuljahr und der Abschnitt abgefragt, für den die Eingaben vorgenommen werden sollen.</p><p><a href="/bilder/vorbereitung/gruppenprozesse-noten-mahnungen-fs-2-eingabemaske.png"><img src="'+o+'" alt="Sortierung beziehungsweise weitere Filterung der Schülermenge, dann Eingabe der Daten." loading="lazy"></a></p><p><em>Sortierung beziehungsweise weitere Filterung der Schülermenge, dann Eingabe der Daten.</em></p><p>Die Eingabemaske zeigt die ausgewählte Schülergruppe. Wählen Sie eine der drei Sortierreihenfolgen:</p><ol><li><strong>Fach, dann Schüler:</strong> geeignet, wenn Sie eine Notenliste für ein bestimmtes Fach vorliegen haben.</li><li><strong>Schüler, dann Fach:</strong> zeigt die Angaben einer Person in allen Fächern zusammen.</li><li>zuerst nach einem Kurs, dann nach den Schülern (entspricht im Prinzip der Sortierung Fach, Schüler)</li></ol><p>Zusätzlich werden auch noch weitere <em>Filtermöglichkeiten</em> angeboten. Diese sind sehr praktisch, um Eintragungen für einen Kurs vorzunehmen.</p>',13),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Wenn Sie einen Kurs gewählt haben, der Personen aus mehreren Klassen enthält, stellen Sie die "),e("em",null,"Sortierung"),n(" noch auf "),e("em",null,"Schüler, Fach"),n(", um die Schüler auf jeden Fall alphabetisch sortiert zu haben.")])],-1),e("h2",{id:"_2-noten-mahnungen-und-fehlstunden-erfassen",tabindex:"-1"},[n("2. Noten, Mahnungen und Fehlstunden erfassen "),e("a",{class:"header-anchor",href:"#_2-noten-mahnungen-und-fehlstunden-erfassen","aria-label":'Permalink to "2. Noten, Mahnungen und Fehlstunden erfassen"'},"​")],-1),e("p",null,[n("Das Setzen der Häkchen bei den "),e("em",null,"Mahnungen"),n(" erfolgt durch einen Doppelklick, die Eintragungen bei den "),e("em",null,"Fehlstunden"),n(" (FSG=Fehlstunden gesamt, FSU=Fehlstunden unentschuldigt) und den Noten durch Klick auf das entsprechende Tabellenfeld. Die Noten können auch aus dem Dropdown-Menü ausgewählt werden.")],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Wenn Sie die Unentschuldigten Fehlstunden zuerst eintragen bzw. mehr UE als FS, werden die Gesamtfehlstunden automatisch auf diesen Wert gesetzt.")],-1),t('<p>In der Sekundarstufe II kann durch einen Klick auf den Spaltentitel <em>Noten</em> auf eine Eingabe und Anzeige von <em>Punkten</em> umgeschaltet werden.</p><p>In Jahrgängen, in denen keine Mahnungen vorgesehen sind, z.B. in der Qualifikationsphase, wird die Spalte <em>Mahnen</em> nicht angezeigt.</p><p>Nach Abschluss der Eingabe werden die Daten durch Kick auf die Schaltfläche <code>In die Datenbank übernehmen</code> gespeichert.</p><p><code>Abbrechen</code> verlässt dieses Fenster, ohne Änderungen in die Datenbank zu übernehmen.</p><p><a href="/bilder/vorbereitung/gruppenprozesse-noten-mahnungen-fs-3-erweiterte-noten.png"><img src="'+l+'" alt="Die Eingabe von erweiterten Noten in der SI erlauben." loading="lazy"></a></p><p><em>Die Eingabe von erweiterten Noten in der SI erlauben.</em></p><p>Möchten Sie in der Sekundarstufe I <em>Noten mit Tendenz</em> geben, können Sie diese Möglichkeit über <em>&quot;Verwaltung Einstellungen Fächer, Noten&quot;</em> mit dem Haken in dem Kasten <em>Fächer, Noten</em> bei <strong>Erweiterte Noten in Sek. I zulassen</strong> ermöglichen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Noten,_Mahnungen_und_Fehlstd._eingeben_(Gruppenprozesse_Noten,_Zeugnisvorbereitung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5390.</p>',9)])])}const _=i(h,[["render",d]]);export{z as __pageData,_ as default};
